"""Run Maven Dash checks for Java and frontend content; submit reviews only with --submit.

The reactor Mojo cannot read npm input, so the frontend/review calls use the same
Dash core through Maven exec:java with System.exit intercepted in-process.
Exit codes: 0 approved, 1 review remains necessary, 2 incomplete/tool/network error.
"""

import argparse
import csv
from datetime import datetime, timezone
import getpass
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import uuid
import xml.etree.ElementTree as ET

PROJECT = "technology.rdf4j"
EXEC_PLUGIN = "org.codehaus.mojo:exec-maven-plugin:3.6.2:java"
TOKEN_ENV = "RDF4J_DASH_REVIEW_TOKEN"
MAVEN_OPTIONS = ("MAVEN_OPTS", "MAVEN_ARGS", "JAVA_TOOL_OPTIONS", "JDK_JAVA_OPTIONS", "_JAVA_OPTIONS")
NETWORK_ERROR = re.compile(
    r"UnknownHostException|ConnectException|SocketTimeoutException|SSLHandshakeException|"
    r"Error communicating|Error contacting|"
    r"\bHTTP(?:/\d(?:\.\d)?)?(?:\s+(?:response|status|code))*\s*[:=]?\s*(?:429|5\d\d)\b|"
    r"HttpResponseException[^\n]*\b(?:429|5\d\d)\b|(?:Exit code:|return code)\s*127", re.IGNORECASE)
NS = {"m": "http://maven.apache.org/POM/4.0.0"}


class CheckError(Exception):
    pass


def npm_id(name, version):
    if not re.fullmatch(r"(?:@[^/\s]+/)?[^/\s]+", name) or not re.fullmatch(
            r"\d+\.\d+\.\d+(?:-[\w.-]+)?(?:\+[\w.-]+)?", version):
        raise CheckError("A dependency has an unsupported name/version; no input was omitted.")
    namespace, package = name.split("/", 1) if name.startswith("@") else ("-", name)
    return f"npm/npmjs/{namespace}/{package}/{version}"


def frontend_inventory(repo):
    tracked = subprocess.run(["git", "-C", str(repo), "ls-files", "-z", "--", "*package-lock.json"],
                             check=True, capture_output=True, text=True).stdout.split("\0")
    locks = [repo / path for path in tracked if path]
    if not locks:
        raise CheckError("No tracked npm lockfiles were found.")
    identities = set()
    for lock in locks:
        data = json.loads(lock.read_text())
        if data.get("lockfileVersion") not in (2, 3) or "packages" not in data:
            raise CheckError(f"Unsupported npm lockfile: {lock.relative_to(repo)}")
        manifest = json.loads(lock.with_name("package.json").read_text())
        root = data["packages"].get("", {})
        for section in ("dependencies", "devDependencies", "optionalDependencies"):
            if manifest.get(section, {}) != root.get(section, {}):
                raise CheckError(f"Lockfile does not match its manifest: {lock.relative_to(repo)}")
        for location, package in data["packages"].items():
            if not location or package.get("link"):
                continue
            name = package.get("name") or location.rsplit("node_modules/", 1)[-1]
            identities.add(npm_id(name, package.get("version", "")))
    vendors = json.loads((repo / "tools/workbench/frontend-vendor-dependencies.json").read_text())
    if vendors.get("schemaVersion") != 1 or not vendors.get("dependencies"):
        raise CheckError("Unsupported or empty vendored dependency inventory.")
    hashes = {}
    for package in vendors["dependencies"]:
        if not package.get("files"):
            raise CheckError("A vendored dependency has no provenance files.")
        for relative in package["files"]:
            path = (repo / relative).resolve()
            if not path.is_relative_to(repo) or not path.is_file():
                raise CheckError(f"Invalid vendored file: {relative}")
            if relative not in hashes:
                hashes[relative] = hashlib.sha256(path.read_bytes()).hexdigest()
            if hashes[relative] != package.get("sha256", {}).get(relative):
                raise CheckError(f"Vendored file does not match its inventory: {relative}")
        identities.add(npm_id(package["name"], package["version"]))
    return identities, vendors.get("bundleLimitations", [])


def safe_maven_environment(repo, maven):
    # Empty token/project strings do not disable the native Mojo's review collector.
    marker = re.compile(r"dash\.(?:iplab\.token|projectId)")
    for key in MAVEN_OPTIONS:
        if marker.search(os.environ.get(key, "")):
            raise CheckError(f"Unset native Dash review configuration in {key}; use DASH_IPLAB_TOKEN with --submit.")
    settings = [repo / ".mvn/maven.config", repo / ".mvn/jvm.config", repo / "pom.xml",
                Path.home() / ".m2/settings.xml", Path(maven).resolve().parent.parent / "conf/settings.xml"]
    for key in ("MAVEN_HOME", "M2_HOME"):
        if os.environ.get(key):
            settings.append(Path(os.environ[key]) / "conf/settings.xml")
    for path in settings:
        if not path.is_file():
            continue
        if path.suffix == ".xml":
            tree = ET.parse(path)
            configured = any(element.tag.rsplit("}", 1)[-1] in ("dash.iplab.token", "dash.projectId")
                             for element in tree.iter())
            for plugin in tree.iter():
                if plugin.tag.rsplit("}", 1)[-1] != "plugin":
                    continue
                fields = {element.tag.rsplit("}", 1)[-1]: element for element in plugin}
                if fields.get("artifactId") is None or fields["artifactId"].text != "license-tool-plugin":
                    continue
                group = fields.get("groupId")
                if group is not None and group.text != "org.eclipse.dash":
                    continue
                configuration = fields.get("configuration")
                configured |= configuration is not None and any(
                    element.tag.rsplit("}", 1)[-1] in ("iplabToken", "projectId") for element in configuration)
        else:
            configured = bool(marker.search(path.read_text()))
        if configured:
            raise CheckError(f"Native Dash review configuration must be absent from {path}; no Maven check was run.")
    environment = dict(os.environ)
    for key in (*MAVEN_OPTIONS, "DASH_IPLAB_TOKEN", TOKEN_ENV):
        environment.pop(key, None)
    environment["MAVEN_SKIP_RC"] = "true"
    return environment


def bridge_pom(path, version, input_file, summary, submit=False):
    project = ET.Element("project", xmlns=NS["m"])
    for key, value in (("modelVersion", "4.0.0"), ("groupId", "org.eclipse.rdf4j.tools"),
                       ("artifactId", "dash-license-input"), ("version", "1")):
        ET.SubElement(project, key).text = value
    repository = ET.SubElement(ET.SubElement(project, "repositories"), "repository")
    ET.SubElement(repository, "id").text = "eclipse-dash"
    ET.SubElement(repository, "url").text = "https://repo.eclipse.org/content/groups/releases/"
    dependency = ET.SubElement(ET.SubElement(project, "dependencies"), "dependency")
    for key, value in (("groupId", "org.eclipse.dash"), ("artifactId", "org.eclipse.dash.licenses"),
                       ("version", version)):
        ET.SubElement(dependency, key).text = value
    plugin = ET.SubElement(ET.SubElement(ET.SubElement(project, "build"), "plugins"), "plugin")
    for key, value in zip(("groupId", "artifactId", "version"), EXEC_PLUGIN.split(":")[:3]):
        ET.SubElement(plugin, key).text = value
    configuration = ET.SubElement(plugin, "configuration")
    ET.SubElement(configuration, "mainClass").text = "org.eclipse.dash.licenses.cli.Main"
    ET.SubElement(configuration, "blockSystemExit").text = "true"
    arguments = ET.SubElement(configuration, "arguments")
    values = [str(input_file), "-summary", str(summary)]
    if submit:
        values += ["-review", "-project", PROJECT, "-token", "$" + "{env." + TOKEN_ENV + "}"]
    for value in values:
        ET.SubElement(arguments, "argument").text = value
    ET.indent(project)
    ET.ElementTree(project).write(path, encoding="utf-8", xml_declaration=True)


def run_maven(command, repo, environment, log, token=None):
    result = subprocess.run(command, cwd=repo, env=environment, text=True,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    output = result.stdout.replace(token, "[REDACTED]") if token else result.stdout
    log.write_text(output)
    return result.returncode, output


def read_report(path, result, expected=None):
    code, output = result
    if NETWORK_ERROR.search(output) or not path.is_file():
        raise CheckError(f"Maven/tool/network failure; inspect retained Maven logs beside {path.name}.")
    rows = {}
    for row in csv.reader(path.read_text().splitlines(), skipinitialspace=True):
        if len(row) < 4 or row[-2].strip() not in ("approved", "restricted"):
            raise CheckError(f"Invalid Dash summary: {path.name}")
        identity, status = row[0].strip(), row[-2].strip()
        if identity in rows:
            raise CheckError(f"Duplicate dependency in Dash summary: {path.name}")
        rows[identity] = {"license": ", ".join(row[1:-2]).strip(), "status": status,
                          "authority": row[-1].strip()}
    if not rows or (expected is not None and rows.keys() != expected):
        raise CheckError(f"Incomplete Dash summary: {path.name}")
    restricted = {identity for identity, row in rows.items() if row["status"] == "restricted"}
    if code not in (0, 1) or (code and not restricted):
        raise CheckError(f"Maven failed independently of license review: {path.name}")
    if code:
        if expected is None:
            review_failure = re.search(
                r"\[ERROR\] Failed to execute goal org\.eclipse\.dash:license-tool-plugin:"
                r"[^:\s]+:license-check[^\n]*Some dependencies must be vetted\.", output)
        else:
            status = re.search(r"\[ERROR\][^\n]*System::exit was called with return code (\d+)", output)
            review_failure = status is not None and int(status[1]) == min(len(restricted), 126)
        if not review_failure:
            raise CheckError(f"Unrelated Maven failure despite a license report: {path.name}")
    return rows


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parent.parent)
    parser.add_argument("--output-dir", type=Path, help="New, nonexistent report directory; stale reports are never reused.")
    parser.add_argument("--online", action="store_true", help="Allow Maven to download missing tool artifacts.")
    parser.add_argument("--submit", action="store_true", help="After fresh checks, request IPLab reviews (up to100/run). "
                        "Uses DASH_IPLAB_TOKEN or a hidden prompt; approvals remain pending.")
    options = parser.parse_args()
    repo = options.repo.resolve()
    maven = shutil.which("mvn")
    if not maven:
        raise CheckError("Maven executable was not found.")
    environment = safe_maven_environment(repo, maven)
    frontend, limitations = frontend_inventory(repo)
    version = ET.parse(repo / "pom.xml").find(
        ".//m:profile[m:id='licence-check']/m:build/m:plugins/m:plugin"
        "[m:artifactId='license-tool-plugin']/m:version", NS)
    if version is None or not version.text or "$" + "{" in version.text:
        raise CheckError("Cannot determine the pinned Dash version from the licence-check profile.")
    output = (options.output_dir or repo / "logs/licenses" / (
        datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ-") + uuid.uuid4().hex[:8])).resolve()
    if output.exists():
        raise CheckError("The output directory already exists; choose a new directory for a fresh scan.")
    output.mkdir(parents=True, mode=0o700)
    input_file = output / "frontend-dependencies.txt"
    input_file.write_text("\n".join(sorted(frontend)) + "\n")
    base = [maven, "-B", "-ntp", "-Dstyle.color=never", "-Dmaven.repo.local=.m2_repo"] + ([] if options.online else ["-o"])
    java_summary, frontend_summary = output / "java-summary.csv", output / "frontend-summary.csv"
    java_result = run_maven(base + ["-f", str(repo / "pom.xml"), "-Plicence-check",
                            f"org.eclipse.dash:license-tool-plugin:{version.text}:license-check",
                            "-Ddash.summary=" + str(java_summary)], repo, environment, output / "java-maven.log")
    frontend_pom = output / "frontend-license-pom.xml"
    bridge_pom(frontend_pom, version.text, input_file, frontend_summary)
    frontend_result = run_maven(base + ["-f", str(frontend_pom), EXEC_PLUGIN], repo, environment,
                                output / "frontend-maven.log")
    java_rows = read_report(java_summary, java_result)
    frontend_rows = read_report(frontend_summary, frontend_result, frontend)
    rows = java_rows | frontend_rows
    restricted = sorted(identity for identity, row in rows.items() if row["status"] == "restricted")
    (output / "results.json").write_text(json.dumps({"project": PROJECT, "dependencies": rows,
        "needsReview": restricted, "bundleLimitations": limitations}, indent=2) + "\n")
    print(f"Checked {len(java_rows)} Maven and {len(frontend_rows)} frontend coordinates; "
          f"{len(restricted)} require review. Reports: {output}")
    if not restricted:
        return 0
    for identity in restricted:
        print(identity)
    if not options.submit:
        print("No issues submitted. Run this script with --submit for fresh checks and explicit IPLab submission.")
        return 1
    token = os.environ.get("DASH_IPLAB_TOKEN") or getpass.getpass("Eclipse GitLab token (api scope): ")
    if not token.strip():
        raise CheckError("No token supplied; no issues submitted.")
    review_input, review_summary = output / "review-dependencies.txt", output / "review-summary.csv"
    review_input.write_text("\n".join(restricted) + "\n")
    review_pom = output / "review-license-pom.xml"
    bridge_pom(review_pom, version.text, review_input, review_summary, submit=True)
    review_environment = dict(environment, **{TOKEN_ENV: token})
    review_result = run_maven(base + ["-f", str(review_pom), EXEC_PLUGIN], repo, review_environment,
                              output / "review-maven.log", token)
    review_rows = read_report(review_summary, review_result, set(restricted))
    rows.update(review_rows)
    remaining = sorted(identity for identity, row in rows.items() if row["status"] == "restricted")
    (output / "results.json").write_text(json.dumps({"project": PROJECT, "dependencies": rows,
        "needsReview": remaining, "bundleLimitations": limitations}, indent=2) + "\n")
    print(f"After fresh review, {len(remaining)} coordinates still require approval. "
          "Inspect review-maven.log for issue URLs; Dash requests at most100 reviews/run.")
    return 1 if remaining else 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (CheckError, OSError, ValueError, KeyError, ET.ParseError, subprocess.CalledProcessError, EOFError) as error:
        print(f"License check incomplete: {error}", file=sys.stderr)
        sys.exit(2)
